void reset_signal_handlers(struct task_struct *t, int force_default) {
    for (int i = 0; i < _NSIG; i++) {
        sigset_t *set = &t->blocked;
        struct ksignal *ksig = &t->pending.signal;

        if (force_default || ksig->handler[i] != SIG_IGN) {
            ksig->handler[i] = SIG_DFL;
            sigemptyset(&ksig->mask[i]);
            sigdelset(set, i);
        }
    }
}

void reset_signal_handlers(struct task_struct *t, int force_default) {
    int i;
    struct ksignal *ksig;

    for (i = 0; i < MAX_SIGNALS; i++) {
        ksig = &t->signals[i];

        if (force_default || ksig->handler != SIG_IGN) {
            ksig->handler = SIG_DFL;
            ksig->flags = 0;
            sigemptyset(&ksig->mask);
        }
    }
}

